"""styles.xml and theme1.xml: the style hierarchy and theme lookups."""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Optional

from ..oxml import find, findall, get, local, val
from .props import (CellProps, ParaProps, RowProps, RunProps, TableProps,
                    parse_ppr, parse_rpr, parse_tblpr, parse_tcpr, parse_trpr)

# w:themeColor value -> theme colour scheme key
THEME_COLOR_MAP = {
    'dark1': 'dk1', 'text1': 'dk1', 'dk1': 'dk1',
    'light1': 'lt1', 'background1': 'lt1', 'lt1': 'lt1',
    'dark2': 'dk2', 'text2': 'dk2', 'dk2': 'dk2',
    'light2': 'lt2', 'background2': 'lt2', 'lt2': 'lt2',
    'accent1': 'accent1', 'accent2': 'accent2', 'accent3': 'accent3',
    'accent4': 'accent4', 'accent5': 'accent5', 'accent6': 'accent6',
    'hyperlink': 'hlink', 'followedHyperlink': 'folHlink',
}

DEFAULT_SCHEME = {
    'dk1': '000000', 'lt1': 'FFFFFF', 'dk2': '44546A', 'lt2': 'E7E6E6',
    'accent1': '4472C4', 'accent2': 'ED7D31', 'accent3': 'A5A5A5',
    'accent4': 'FFC000', 'accent5': '5B9BD5', 'accent6': '70AD47',
    'hlink': '0563C1', 'folHlink': '954F72',
}


class Theme:
    """Font and colour scheme from theme1.xml."""

    def __init__(self, root=None):
        self.major_font = 'Calibri Light'
        self.minor_font = 'Calibri'
        self.colors = dict(DEFAULT_SCHEME)
        if root is None:
            return
        scheme = find(root, 'a:themeElements')
        if scheme is None:
            return
        font_scheme = find(scheme, 'a:fontScheme')
        if font_scheme is not None:
            major = find(font_scheme, 'a:majorFont/a:latin')
            minor = find(font_scheme, 'a:minorFont/a:latin')
            if major is not None and major.get('typeface'):
                self.major_font = major.get('typeface')
            if minor is not None and minor.get('typeface'):
                self.minor_font = minor.get('typeface')
        color_scheme = find(scheme, 'a:clrScheme')
        if color_scheme is not None:
            for child in color_scheme:
                key = local(child.tag)
                srgb = find(child, 'a:srgbClr')
                if srgb is not None and srgb.get('val'):
                    self.colors[key] = srgb.get('val').upper()
                    continue
                sysclr = find(child, 'a:sysClr')
                if sysclr is not None and sysclr.get('lastClr'):
                    self.colors[key] = sysclr.get('lastClr').upper()

    def font(self, theme_name: Optional[str]) -> Optional[str]:
        if not theme_name:
            return None
        if theme_name.startswith('major'):
            return self.major_font
        if theme_name.startswith('minor'):
            return self.minor_font
        return None

    def color(self, name: Optional[str], tint=None, shade=None) -> Optional[str]:
        if not name or name == 'none':
            return None
        key = THEME_COLOR_MAP.get(name, name)
        hex_color = self.colors.get(key)
        if hex_color is None:
            return None
        return apply_tint_shade(hex_color, tint, shade)


def apply_tint_shade(hex_color: str, tint=None, shade=None) -> str:
    try:
        r = int(hex_color[0:2], 16)
        g = int(hex_color[2:4], 16)
        b = int(hex_color[4:6], 16)
    except (ValueError, IndexError):
        return hex_color
    if tint:
        try:
            t = int(tint, 16) / 255.0
        except ValueError:
            t = 1.0
        r = int(round(r * t + 255 * (1 - t)))
        g = int(round(g * t + 255 * (1 - t)))
        b = int(round(b * t + 255 * (1 - t)))
    if shade:
        try:
            s = int(shade, 16) / 255.0
        except ValueError:
            s = 1.0
        r = int(round(r * s))
        g = int(round(g * s))
        b = int(round(b * s))
    return '%02X%02X%02X' % (max(0, min(255, r)), max(0, min(255, g)), max(0, min(255, b)))


@dataclass
class Style:
    id: str
    type: str = 'paragraph'
    name: str = ''
    based_on: Optional[str] = None
    next_style: Optional[str] = None
    link: Optional[str] = None
    default: bool = False
    ppr: ParaProps = field(default_factory=ParaProps)
    rpr: RunProps = field(default_factory=RunProps)
    tblpr: TableProps = field(default_factory=TableProps)
    trpr: RowProps = field(default_factory=RowProps)
    tcpr: CellProps = field(default_factory=CellProps)
    conditional: dict = field(default_factory=dict)


class StyleSheet:
    """Resolved access to the document's styles."""

    def __init__(self, root=None, theme: Optional[Theme] = None):
        self.theme = theme or Theme()
        self.styles: dict[str, Style] = {}
        self.default_para_style: Optional[str] = None
        self.default_char_style: Optional[str] = None
        self.default_table_style: Optional[str] = None
        self.doc_ppr = ParaProps()
        # No font here: docDefaults usually points at the theme's minor font,
        # and a hard-coded family would shadow it.  The size is the format's
        # own default (w:sz is in half-points, and its default is 20).
        self.doc_rpr = RunProps(size=10.0)
        self._para_cache: dict = {}
        self._run_cache: dict = {}
        self._table_cache: dict = {}
        if root is not None:
            self._load(root)

    def _load(self, root):
        defaults = find(root, 'w:docDefaults')
        if defaults is not None:
            rpr = find(defaults, 'w:rPrDefault/w:rPr')
            ppr = find(defaults, 'w:pPrDefault/w:pPr')
            if rpr is not None:
                self.doc_rpr = self.doc_rpr.merge(parse_rpr(rpr, self.theme))
            if ppr is not None:
                self.doc_ppr = self.doc_ppr.merge(parse_ppr(ppr))
        for el in findall(root, 'w:style'):
            style_id = get(el, 'w:styleId')
            if not style_id:
                continue
            style = Style(
                id=style_id,
                type=get(el, 'w:type', 'paragraph'),
                name=val(find(el, 'w:name'), '') or '',
                based_on=val(find(el, 'w:basedOn')),
                next_style=val(find(el, 'w:next')),
                link=val(find(el, 'w:link')),
                default=get(el, 'w:default') in ('1', 'true', 'on'),
                ppr=parse_ppr(find(el, 'w:pPr')),
                rpr=parse_rpr(find(el, 'w:rPr'), self.theme),
                tblpr=parse_tblpr(find(el, 'w:tblPr')),
                trpr=parse_trpr(find(el, 'w:trPr')),
                tcpr=parse_tcpr(find(el, 'w:tcPr')),
            )
            for cond in findall(el, 'w:tblStylePr'):
                ctype = get(cond, 'w:type')
                if not ctype:
                    continue
                style.conditional[ctype] = {
                    'ppr': parse_ppr(find(cond, 'w:pPr')),
                    'rpr': parse_rpr(find(cond, 'w:rPr'), self.theme),
                    'tblpr': parse_tblpr(find(cond, 'w:tblPr')),
                    'trpr': parse_trpr(find(cond, 'w:trPr')),
                    'tcpr': parse_tcpr(find(cond, 'w:tcPr')),
                }
            self.styles[style_id] = style
            if style.default:
                if style.type == 'paragraph' and self.default_para_style is None:
                    self.default_para_style = style_id
                elif style.type == 'character' and self.default_char_style is None:
                    self.default_char_style = style_id
                elif style.type == 'table' and self.default_table_style is None:
                    self.default_table_style = style_id

    # -- lookups ------------------------------------------------------------
    def get(self, style_id) -> Optional[Style]:
        if not style_id:
            return None
        style = self.styles.get(style_id)
        if style is not None:
            return style
        # Word tolerates case/space differences between styleId and name
        target = style_id.replace(' ', '').lower()
        for s in self.styles.values():
            if s.id.replace(' ', '').lower() == target or \
               s.name.replace(' ', '').lower() == target:
                return s
        return None

    def chain(self, style_id) -> list:
        """Style ancestry, root first."""
        out = []
        seen = set()
        current = self.get(style_id)
        while current is not None and current.id not in seen:
            seen.add(current.id)
            out.append(current)
            current = self.get(current.based_on)
        out.reverse()
        return out

    def style_by_name(self, name: str) -> Optional[Style]:
        target = name.replace(' ', '').lower()
        for s in self.styles.values():
            if s.name.replace(' ', '').lower() == target:
                return s
        return None

    def para_props(self, style_id) -> ParaProps:
        key = style_id or ''
        if key in self._para_cache:
            return self._para_cache[key]
        props = self.doc_ppr
        for sid in self._style_ids(style_id):
            for style in self.chain(sid):
                if style.type in ('paragraph', 'numbering'):
                    props = props.merge(style.ppr)
        self._para_cache[key] = props
        return props

    def para_run_props(self, style_id) -> RunProps:
        """Run defaults implied by a paragraph style."""
        key = style_id or ''
        if key in self._run_cache:
            return self._run_cache[key]
        props = self.doc_rpr
        for sid in self._style_ids(style_id):
            for style in self.chain(sid):
                if style.type in ('paragraph', 'numbering'):
                    props = props.merge(style.rpr)
        self._run_cache[key] = props
        return props

    def style_only_ppr(self, style_id) -> ParaProps:
        """Paragraph style chain without the document defaults folded in."""
        props = ParaProps()
        for sid in self._style_ids(style_id):
            for style in self.chain(sid):
                if style.type in ('paragraph', 'numbering'):
                    props = props.merge(style.ppr)
        return props

    def style_only_rpr(self, style_id) -> RunProps:
        props = RunProps()
        for sid in self._style_ids(style_id):
            for style in self.chain(sid):
                if style.type in ('paragraph', 'numbering'):
                    props = props.merge(style.rpr)
        return props

    def _style_ids(self, style_id):
        """The styles to apply, in order.

        The default paragraph style only covers paragraphs that have no style
        of their own; a named style inherits solely through its basedOn chain,
        which is why a style like "No Spacing" keeps the document defaults.
        """
        if style_id and self.get(style_id) is not None:
            return [style_id]
        return [self.default_para_style] if self.default_para_style else [style_id]

    def char_props(self, style_id, base: Optional[RunProps] = None) -> RunProps:
        props = base if base is not None else RunProps()
        for style in self.chain(style_id):
            if style.type == 'character':
                props = props.merge(style.rpr)
        return props

    def table_props(self, style_id):
        """(TableProps, RowProps, CellProps, ParaProps, RunProps) for a style."""
        key = style_id or ''
        if key in self._table_cache:
            return self._table_cache[key]
        tbl, row, cell = TableProps(), RowProps(), CellProps()
        ppr, rpr = ParaProps(), RunProps()
        for style in self.chain(style_id):
            if style.type != 'table':
                continue
            tbl = tbl.merge(style.tblpr)
            row = row.merge(style.trpr)
            cell = cell.merge(style.tcpr)
            ppr = ppr.merge(style.ppr)
            rpr = rpr.merge(style.rpr)
        out = (tbl, row, cell, ppr, rpr)
        self._table_cache[key] = out
        return out

    def table_conditional(self, style_id, ctype):
        """Conditional formatting (firstRow, band1Horz, ...) for a table style."""
        tbl, row, cell = TableProps(), RowProps(), CellProps()
        ppr, rpr = ParaProps(), RunProps()
        found = False
        for style in self.chain(style_id):
            cond = style.conditional.get(ctype)
            if not cond:
                continue
            found = True
            tbl = tbl.merge(cond['tblpr'])
            row = row.merge(cond['trpr'])
            cell = cell.merge(cond['tcpr'])
            ppr = ppr.merge(cond['ppr'])
            rpr = rpr.merge(cond['rpr'])
        if not found:
            return None
        return (tbl, row, cell, ppr, rpr)

    # -- colour helpers -----------------------------------------------------
    def resolve_color(self, props) -> Optional[str]:
        """Effective run colour as 'RRGGBB' (None means automatic/black)."""
        if getattr(props, 'color', None):
            return props.color
        theme_color = getattr(props, 'theme_color', None)
        if theme_color:
            return self.theme.color(theme_color, getattr(props, 'theme_tint', None),
                                    getattr(props, 'theme_shade', None))
        return None

    def resolve_fill(self, shading) -> Optional[str]:
        if shading is None:
            return None
        if shading.pattern in ('nil', 'clear') and not shading.fill and not shading.fill_theme:
            return None
        if shading.fill:
            return shading.fill
        if shading.fill_theme:
            return self.theme.color(shading.fill_theme)
        return None

    def resolve_border_color(self, border) -> Optional[str]:
        if border is None:
            return None
        if border.color:
            return border.color
        if border.theme_color:
            return self.theme.color(border.theme_color)
        return None
